bg=7
panels=[(1, [[1,0,1],[1,0,1],[1,1,1]]),(4,[[1,0,0],[1,1,0],[1,0,1]]),(6,[[1,1,1],[0,1,0],[1,1,1]])]
out=[[bg]*19 for _ in range(7)]
for col,(color,mask) in zip([1,7,13],panels):
    for r in range(1,6):
        for c in range(col,col+5): out[r][c]=color
    for i in range(3):
        for j in range(3):
            if mask[i][j]: out[i+2][col+1+j]=bg
print('\n'.join(' '.join(map(str,row)) for row in out))
